INSERT INTO pwp_audio_assets (key, voice, category, label, storage_path, script)
VALUES
  ('celebration.badge_builder', 'amelia', 'celebration', 'Badge — Builder (Silver)', 'amelia/celebrations/amelia_celebration_badge-builder.mp3', 'The Builder badge is yours! You have shown real command of phrases and sentence variety. Silver level achieved.'),
  ('celebration.badge_composer', 'amelia', 'celebration', 'Badge — Composer (Gold)', 'amelia/celebrations/amelia_celebration_badge-composer.mp3', 'Gold — the Composer badge! Every formula level is complete. You are a sentence builder now.'),
  ('celebration.badge_foundation', 'amelia', 'celebration', 'Badge — Foundation (Bronze)', 'amelia/celebrations/amelia_celebration_badge-foundation.mp3', 'You''ve earned the Foundation badge! Bronze level — you have mastered the building blocks of the sentence.'),
  ('celebration.badge_master', 'amelia', 'celebration', 'Badge — Master (Platinum)', 'amelia/celebrations/amelia_celebration_badge-master.mp3', 'Platinum — Programme Master! All thirteen mastery quizzes passed. That is an extraordinary achievement.'),
  ('celebration.badge_paragraph', 'amelia', 'celebration', 'Badge — Paragraph Writer', 'amelia/celebrations/amelia_celebration_badge-paragraph.mp3', 'The Paragraph Writer badge is earned! You have completed every paragraph phase level. Your writing flows.'),
  ('celebration.chapter_complete', 'amelia', 'celebration', 'Chapter complete', 'amelia/celebrations/amelia_celebration_chapter-complete.mp3', 'Chapter complete! That is a huge milestone. Every formula in this chapter is now part of your writing — for life.'),
  ('celebration.level_complete', 'amelia', 'celebration', 'Level complete', 'amelia/celebrations/amelia_celebration_level-complete.mp3', 'Level complete! Twenty-five bonus XP. You have unlocked the next level — keep that momentum going.'),
  ('celebration.paragraph_phase_unlock', 'amelia', 'celebration', 'Paragraph phase unlock', 'amelia/celebrations/amelia_celebration_paragraph-phase-unlock.mp3', 'The paragraph phase has begun! From now on, your formula sentence opens a full paragraph. This is real writing.'),
  ('celebration.programme_complete', 'amelia', 'celebration', 'Programme complete', 'amelia/celebrations/amelia_celebration_programme-complete.mp3', 'You have completed the PWP programme. Every level. Every formula. Every mastery quiz. You are a writer now — and this is just the beginning.'),
  ('celebration.quiz_checkpoint', 'amelia', 'celebration', 'Quiz checkpoint reached', 'amelia/celebrations/amelia_celebration_quiz-checkpoint.mp3', 'Checkpoint reached! A mastery quiz is now unlocked. This is your chance to show everything you know.'),
  ('celebration.streak_30', 'amelia', 'celebration', '30-day streak', 'amelia/celebrations/amelia_celebration_streak-30.mp3', 'Thirty days! That is a month of writing practice. You should be incredibly proud of that commitment.'),
  ('celebration.streak_7', 'amelia', 'celebration', '7-day streak', 'amelia/celebrations/amelia_celebration_streak-7.mp3', 'Seven days in a row! Thirty bonus XP for your streak. Consistency is what great writers are built on.'),
  ('feedback.correct_v1', 'amelia', 'feedback', 'Correct — variant 1', 'amelia/feedback/amelia_feedback_correct-v1.mp3', 'That''s exactly right. Well done.'),
  ('feedback.correct_v10', 'amelia', 'feedback', 'Correct — variant 10', 'amelia/feedback/amelia_feedback_correct-v10.mp3', 'Correct! And did you notice how much more vivid that sentence is than Sam ran? That is what grammar does.'),
  ('feedback.correct_v11', 'amelia', 'feedback', 'Correct — variant 11', 'amelia/feedback/amelia_feedback_correct-v11.mp3', 'Yes — and well written too. The reader can picture that scene.'),
  ('feedback.correct_v12', 'amelia', 'feedback', 'Correct — variant 12', 'amelia/feedback/amelia_feedback_correct-v12.mp3', 'Spot on. Your formula instincts are getting sharper.'),
  ('feedback.correct_v2', 'amelia', 'feedback', 'Correct — variant 2', 'amelia/feedback/amelia_feedback_correct-v2.mp3', 'Brilliant! You have used the formula perfectly.'),
  ('feedback.correct_v3', 'amelia', 'feedback', 'Correct — variant 3', 'amelia/feedback/amelia_feedback_correct-v3.mp3', 'Yes! That sentence is spot on. Ten XP earned.'),
  ('feedback.correct_v4', 'amelia', 'feedback', 'Correct — variant 4', 'amelia/feedback/amelia_feedback_correct-v4.mp3', 'Excellent work. Every element is in exactly the right place.'),
  ('feedback.correct_v5', 'amelia', 'feedback', 'Correct — variant 5', 'amelia/feedback/amelia_feedback_correct-v5.mp3', 'Perfect. You are building something impressive.'),
  ('feedback.correct_v6', 'amelia', 'feedback', 'Correct — variant 6', 'amelia/feedback/amelia_feedback_correct-v6.mp3', 'Wonderful! That is a strong sentence — clear, controlled, and correct.'),
  ('feedback.correct_v7', 'amelia', 'feedback', 'Correct — variant 7', 'amelia/feedback/amelia_feedback_correct-v7.mp3', 'You''ve got it. Ten XP. On to the next step.'),
  ('feedback.correct_v8', 'amelia', 'feedback', 'Correct — variant 8', 'amelia/feedback/amelia_feedback_correct-v8.mp3', 'That is exactly what we were looking for. Nice work.'),
  ('feedback.correct_v9', 'amelia', 'feedback', 'Correct — variant 9', 'amelia/feedback/amelia_feedback_correct-v9.mp3', 'Superb. You are really getting the hang of this formula.'),
  ('feedback.error_general', 'amelia', 'feedback', 'Error — general', 'amelia/feedback/amelia_feedback_error-general.mp3', 'Not quite — but you are close. Look at the formula again, then look at the example. What is different about your sentence?'),
  ('feedback.error_missing_adjective', 'amelia', 'feedback', 'Error — missing adjective', 'amelia/feedback/amelia_feedback_error-missing-adjective.mp3', 'The formula asks for an adjective in front of the noun. What does the noun look like? Add one describing word and try again.'),
  ('feedback.error_missing_adverb', 'amelia', 'feedback', 'Error — missing adverb', 'amelia/feedback/amelia_feedback_error-missing-adverb.mp3', 'Almost — the adverb is missing. Remember: it tells us how, when, or where. Add it at the end of the sentence.'),
  ('feedback.error_missing_comma', 'amelia', 'feedback', 'Error — missing comma', 'amelia/feedback/amelia_feedback_error-missing-comma.mp3', 'You have moved a word or phrase to the front — brilliant. But do not forget: it needs a comma right after it.'),
  ('feedback.error_missing_conjunction', 'amelia', 'feedback', 'Error — missing conjunction', 'amelia/feedback/amelia_feedback_error-missing-conjunction.mp3', 'Your two clauses need a conjunction to join them. Look at the formula — which conjunction should sit between them?'),
  ('feedback.error_missing_determiner', 'amelia', 'feedback', 'Error — missing determiner', 'amelia/feedback/amelia_feedback_error-missing-determiner.mp3', 'Nearly there! Check the formula — there should be a determiner before that noun. Try adding the or a and see how it reads.'),
  ('feedback.error_missing_object', 'amelia', 'feedback', 'Error — missing object', 'amelia/feedback/amelia_feedback_error-missing-object.mp3', 'Your sentence needs an object — something the subject did the action to. What did they kick, find, or carry? Add it after the verb.'),
  ('feedback.error_missing_preposition', 'amelia', 'feedback', 'Error — missing preposition', 'amelia/feedback/amelia_feedback_error-missing-preposition.mp3', 'Your preposition phrase needs a little more. Check the formula — the preposition should be followed by a determiner and a noun.'),
  ('feedback.error_wrong_pronoun', 'amelia', 'feedback', 'Error — wrong pronoun', 'amelia/feedback/amelia_feedback_error-wrong-pronoun.mp3', 'Check the pronoun. Is the subject male, female, or a thing? He, she, or it — choose the one that fits and try again.'),
  ('feedback.error_wrong_tense', 'amelia', 'feedback', 'Error — wrong tense', 'amelia/feedback/amelia_feedback_error-wrong-tense.mp3', 'The tense needs a small adjustment. Check whether the verb should be past, present, or continuous — then try again.'),
  ('feedback.retry_correct_v1', 'amelia', 'feedback', 'Correct on retry — variant 1', 'amelia/feedback/amelia_feedback_retry-correct-v1.mp3', 'There it is! You worked it out. Five XP.'),
  ('feedback.retry_correct_v2', 'amelia', 'feedback', 'Correct on retry — variant 2', 'amelia/feedback/amelia_feedback_retry-correct-v2.mp3', 'You got there — that is the one. Well done for persisting.'),
  ('feedback.retry_correct_v3', 'amelia', 'feedback', 'Correct on retry — variant 3', 'amelia/feedback/amelia_feedback_retry-correct-v3.mp3', 'Correct this time. Notice what changed — that is what to remember.'),
  ('feedback.retry_correct_v4', 'amelia', 'feedback', 'Correct on retry — variant 4', 'amelia/feedback/amelia_feedback_retry-correct-v4.mp3', 'Yes! That is right. Five XP earned. Keep going.'),
  ('feedback.retry_correct_v5', 'amelia', 'feedback', 'Correct on retry — variant 5', 'amelia/feedback/amelia_feedback_retry-correct-v5.mp3', 'Good — you fixed it. That is exactly how writers improve.'),
  ('feedback.retry_correct_v6', 'amelia', 'feedback', 'Correct on retry — variant 6', 'amelia/feedback/amelia_feedback_retry-correct-v6.mp3', 'Well done for trying again. That sentence is correct now.'),
  ('feedback.retry_correct_v7', 'amelia', 'feedback', 'Correct on retry — variant 7', 'amelia/feedback/amelia_feedback_retry-correct-v7.mp3', 'Second time — nailed it. Five XP.'),
  ('feedback.retry_correct_v8', 'amelia', 'feedback', 'Correct on retry — variant 8', 'amelia/feedback/amelia_feedback_retry-correct-v8.mp3', 'That is the correct formula. You spotted your error — that is a real writing skill.'),
  ('gamification.first_correct', 'amelia', 'gamification', 'First correct answer', 'amelia/gamification/amelia_gamification_first-correct.mp3', 'First correct answer — you are off to a great start!'),
  ('gamification.halfway', 'amelia', 'gamification', 'Halfway through level', 'amelia/gamification/amelia_gamification_halfway.mp3', 'Halfway through the level! Keep going — you are doing brilliantly.'),
  ('gamification.lives_lost_one', 'amelia', 'gamification', 'One life lost', 'amelia/gamification/amelia_gamification_lives-lost-one.mp3', 'One life lost — four remaining. Read the formula carefully and try again.'),
  ('gamification.lives_zero', 'amelia', 'gamification', 'No lives remaining', 'amelia/gamification/amelia_gamification_lives-zero.mp3', 'No lives left for this session. Take a break and come back fresh — your progress is saved.'),
  ('gamification.streak_broken', 'amelia', 'gamification', 'Streak broken', 'amelia/gamification/amelia_gamification_streak-broken.mp3', 'Your streak reset — but your XP and levels are safe. Start a new one today.'),
  ('gamification.streak_continue', 'amelia', 'gamification', 'Streak continue', 'amelia/gamification/amelia_gamification_streak-continue.mp3', 'Streak kept! Come back tomorrow to keep it going.'),
  ('gamification.xp_10', 'amelia', 'gamification', 'XP: +10', 'amelia/gamification/amelia_gamification_xp-10.mp3', 'Plus ten XP!'),
  ('gamification.xp_25_bonus', 'amelia', 'gamification', 'XP: +25 level bonus', 'amelia/gamification/amelia_gamification_xp-25-bonus.mp3', 'Level bonus — twenty-five XP!'),
  ('gamification.xp_5', 'amelia', 'gamification', 'XP: +5', 'amelia/gamification/amelia_gamification_xp-5.mp3', 'Plus five XP.'),
  ('gamification.xp_50_bonus', 'amelia', 'gamification', 'XP: +50 quiz bonus', 'amelia/gamification/amelia_gamification_xp-50-bonus.mp3', 'Quiz bonus — fifty XP!'),
  ('guidance.adaptive_open', 'alistair', 'guidance', 'Adaptive guidance trigger', 'alistair/guidance/alistair_guidance_adaptive-open.mp3', 'Here is a brief explanation of why this works. Understanding the rule helps you use it anywhere.'),
  ('guidance.explain_adjective', 'alistair', 'guidance', 'Explain: adjective', 'alistair/guidance/alistair_guidance_explain-adjective.mp3', 'An adjective describes a noun. Tall, red, and dark are adjectives. They sit directly before the noun they describe.'),
  ('guidance.explain_adverb_manner', 'alistair', 'guidance', 'Explain: adverb of manner', 'alistair/guidance/alistair_guidance_explain-adverb-manner.mp3', 'An adverb of manner tells us how something happened. Quickly, hard, and slowly are adverbs of manner.'),
  ('guidance.explain_adverb_place', 'alistair', 'guidance', 'Explain: adverb of place', 'alistair/guidance/alistair_guidance_explain-adverb-place.mp3', 'An adverb of place tells us where something happened. Outside, here, and nearby are adverbs of place.'),
  ('guidance.explain_adverb_time', 'alistair', 'guidance', 'Explain: adverb of time', 'alistair/guidance/alistair_guidance_explain-adverb-time.mp3', 'An adverb of time tells us when something happened. Yesterday, today, and soon are adverbs of time.'),
  ('guidance.explain_conjunction_coord', 'alistair', 'guidance', 'Explain: coordinating conjunction', 'alistair/guidance/alistair_guidance_explain-conjunction-coord.mp3', 'A coordinating conjunction joins two main clauses as equals. And, but, or, so, yet, and for are coordinating conjunctions.'),
  ('guidance.explain_conjunction_sub', 'alistair', 'guidance', 'Explain: subordinating conjunction', 'alistair/guidance/alistair_guidance_explain-conjunction-sub.mp3', 'A subordinating conjunction joins a main clause to a dependent clause. Because, when, and although are common subordinating conjunctions.'),
  ('guidance.explain_determiner', 'alistair', 'guidance', 'Explain: determiner', 'alistair/guidance/alistair_guidance_explain-determiner.mp3', 'A determiner comes before a noun and tells the reader which one. The and a are the most common determiners.'),
  ('guidance.explain_fronted_adverbial', 'alistair', 'guidance', 'Explain: fronted adverbial', 'alistair/guidance/alistair_guidance_explain-fronted-adverbial.mp3', 'A fronted adverbial is any adverb or adverb phrase placed at the start of a sentence. It must be followed by a comma.'),
  ('guidance.explain_noun', 'alistair', 'guidance', 'Explain: noun', 'alistair/guidance/alistair_guidance_explain-noun.mp3', 'A noun is a naming word — a person, place, or thing. Sam, school, and ball are all nouns.'),
  ('guidance.explain_noun_phrase', 'alistair', 'guidance', 'Explain: noun phrase', 'alistair/guidance/alistair_guidance_explain-noun-phrase.mp3', 'A noun phrase is a group of words built around a noun — determiner, adjectives, and the noun together. The very tall boy is a noun phrase.'),
  ('guidance.explain_preposition', 'alistair', 'guidance', 'Explain: preposition', 'alistair/guidance/alistair_guidance_explain-preposition.mp3', 'A preposition shows the relationship between a noun and the rest of the sentence — usually position or direction. Into, under, and beside are prepositions.'),
  ('guidance.explain_pronoun', 'alistair', 'guidance', 'Explain: pronoun', 'alistair/guidance/alistair_guidance_explain-pronoun.mp3', 'A pronoun replaces a noun. Instead of saying The boy again and again, we say He. It saves repetition and creates flow.'),
  ('guidance.explain_relative_clause', 'alistair', 'guidance', 'Explain: relative clause', 'alistair/guidance/alistair_guidance_explain-relative-clause.mp3', 'A relative clause is embedded inside a noun phrase using who, which, or that. The boy who trained every day — who trained every day is the relative clause.'),
  ('guidance.explain_rule', 'alistair', 'guidance', 'Guidance L3 — Explain rule', 'alistair/guidance/alistair_guidance_explain-rule.mp3', 'Here is a brief explanation of why this works. Understanding the rule helps you use it anywhere.'),
  ('guidance.explain_transition', 'alistair', 'guidance', 'Explain: transitional phrase', 'alistair/guidance/alistair_guidance_explain-transition.mp3', 'A transitional phrase at the start of a sentence guides the reader from one idea to the next. First, however, and as a result are transitional phrases.'),
  ('guidance.explain_verb', 'alistair', 'guidance', 'Explain: verb', 'alistair/guidance/alistair_guidance_explain-verb.mp3', 'A verb is a doing or being word. Ran, kicks, and is running are all verbs.'),
  ('guidance.model_sentence', 'alistair', 'guidance', 'Guidance L2 — Model sentence', 'alistair/guidance/alistair_guidance_model-sentence.mp3', 'Here is a worked example using a different subject. Use it as a model — do not copy it.'),
  ('guidance.remind_formula', 'alistair', 'guidance', 'Guidance L1 — Remind formula', 'alistair/guidance/alistair_guidance_remind-formula.mp3', 'Here is the formula broken into its parts. Each word class is colour-coded. Build your sentence piece by piece.'),
  ('onboarding.first_login', 'amelia', 'onboarding', 'Onboarding — first login', 'amelia/onboarding/amelia_onboarding_first-login.mp3', 'Welcome to WriFe Progressive Writing Practice! I am Amelia, and I will be here to cheer you on. Every level builds on the last — take it one step at a time.'),
  ('onboarding.returning_user', 'amelia', 'onboarding', 'Onboarding — returning user', 'amelia/onboarding/amelia_onboarding_returning-user.mp3', 'Welcome back! Your progress is saved — pick up exactly where you stopped.'),
  ('onboarding.what_is_chain', 'amelia', 'onboarding', 'Onboarding — what is a chain', 'amelia/onboarding/amelia_onboarding_what-is-chain.mp3', 'Each level has a chain of steps. The steps get longer as the level goes on. Start at step one and build up. You are always in control.'),
  ('onboarding.what_is_formula', 'amelia', 'onboarding', 'Onboarding — what is a formula', 'amelia/onboarding/amelia_onboarding_what-is-formula.mp3', 'A formula shows you the shape of a sentence. Think of it as a recipe — the formula tells you the ingredients and the order. You provide the words.'),
  ('onboarding.xp_explained', 'amelia', 'onboarding', 'Onboarding — XP explained', 'amelia/onboarding/amelia_onboarding_xp-explained.mp3', 'Every correct sentence earns XP. First attempt: ten points. Retry: five points. Complete a level and earn a bonus twenty-five. Watch your star fill up!'),
  ('quiz.all_prompts_visible', 'alistair', 'quiz', 'Quiz — all prompts visible', 'alistair/quiz/alistair_quiz_all-prompts-visible.mp3', 'You can see all the prompts. Work through them at your own pace. There is no rush.'),
  ('quiz.check_formula', 'alistair', 'quiz', 'Quiz — check formula reminder', 'alistair/quiz/alistair_quiz_check-formula.mp3', 'Check: does your sentence match the formula? Every element in the formula should appear in your sentence.'),
  ('quiz.check_tense', 'alistair', 'quiz', 'Quiz — check tense reminder', 'alistair/quiz/alistair_quiz_check-tense.mp3', 'Check: have you used the correct tense? Read your sentence back before you submit.'),
  ('quiz.fail_v1', 'amelia', 'quiz', 'Quiz fail — variant 1', 'amelia/quiz/amelia_quiz_fail-v1.mp3', 'Not quite there yet — but you are close. Review the steps that felt tricky, then try the quiz again. You can do this.'),
  ('quiz.fail_v2', 'amelia', 'quiz', 'Quiz fail — variant 2', 'amelia/quiz/amelia_quiz_fail-v2.mp3', 'The quiz needs another attempt. That is completely fine — look at the feedback on each prompt, then have another go.'),
  ('quiz.fail_v3', 'amelia', 'quiz', 'Quiz fail — variant 3', 'amelia/quiz/amelia_quiz_fail-v3.mp3', 'Almost there. Two or three prompts need another look. Use the guidance on each one, then try again.'),
  ('quiz.here_is_prompt', 'alistair', 'quiz', 'Quiz — here is your prompt', 'alistair/quiz/alistair_quiz_here-is-prompt.mp3', 'Here is your prompt. Read it carefully, then write your sentence in the tense or form shown.'),
  ('quiz.pass_v1', 'amelia', 'quiz', 'Quiz pass — variant 1', 'amelia/quiz/amelia_quiz_pass-v1.mp3', 'You passed! Mastery Quiz complete. A checkpoint badge has been added to your collection.'),
  ('quiz.pass_v2', 'amelia', 'quiz', 'Quiz pass — variant 2', 'amelia/quiz/amelia_quiz_pass-v2.mp3', 'Excellent work on the quiz. You have demonstrated real control of these structures. Next level is now unlocked.'),
  ('quiz.pass_v3', 'amelia', 'quiz', 'Quiz pass — variant 3', 'amelia/quiz/amelia_quiz_pass-v3.mp3', 'Quiz passed! Fifty bonus XP earned. You are ready for the next set of levels.'),
  ('quiz.pass_v4', 'amelia', 'quiz', 'Quiz pass — variant 4', 'amelia/quiz/amelia_quiz_pass-v4.mp3', 'Congratulations — checkpoint cleared. Your writing toolkit just got bigger.'),
  ('quiz.pass_v5', 'amelia', 'quiz', 'Quiz pass — variant 5', 'amelia/quiz/amelia_quiz_pass-v5.mp3', 'Well done on the mastery quiz. Every answer showed solid understanding. Keep going!'),
  ('quiz.start_quiz_01', 'alistair', 'quiz', 'Quiz 1 Start — Tense Check', 'alistair/quiz/alistair_quiz_start-quiz-01.mp3', 'Mastery Quiz One — Tense Check. You have practised the past, present, and continuous tense. Six prompts. Write each sentence in the tense shown. Show what you know.'),
  ('quiz.start_quiz_02', 'alistair', 'quiz', 'Quiz 2 Start — Determiner Check', 'alistair/quiz/alistair_quiz_start-quiz-02.mp3', 'Mastery Quiz Two — Determiner Check. Five prompts. Use the correct determiner on the subject and the object. Show that you know where each one goes.'),
  ('quiz.start_quiz_03', 'alistair', 'quiz', 'Quiz 3 Start — Adjective Check', 'alistair/quiz/alistair_quiz_start-quiz-03.mp3', 'Mastery Quiz Three — Adjective Check. Six prompts. Place adjectives correctly on the subject noun, the object noun, or both. One step at a time.'),
  ('quiz.start_quiz_04', 'alistair', 'quiz', 'Quiz 4 Start — Adverb Check', 'alistair/quiz/alistair_quiz_start-quiz-04.mp3', 'Mastery Quiz Four — Adverb Check. All three adverb types: manner, time, and place. Six prompts. Show that you can tell them apart and place them correctly.'),
  ('quiz.start_quiz_05', 'alistair', 'quiz', 'Quiz 5 Start — Pronoun Check', 'alistair/quiz/alistair_quiz_start-quiz-05.mp3', 'Mastery Quiz Five — Pronoun Check. Six prompts. Replace the noun subject with the correct pronoun. He, she, or it — choose carefully.'),
  ('quiz.start_quiz_06', 'alistair', 'quiz', 'Quiz 6 Start — Preposition Check', 'alistair/quiz/alistair_quiz_start-quiz-06.mp3', 'Mastery Quiz Six — Preposition Check. Five prompts. Build a full preposition phrase: preposition, determiner, adjective, noun. Precise and controlled.'),
  ('quiz.start_quiz_07', 'alistair', 'quiz', 'Quiz 7 Start — Sentence Purpose Check', 'alistair/quiz/alistair_quiz_start-quiz-07.mp3', 'Mastery Quiz Seven — Sentence Purpose Check. Questions, commands, and exclamations. Five prompts. Change the sentence type as instructed — the words you need are already in your toolkit.'),
  ('quiz.start_quiz_08', 'alistair', 'quiz', 'Quiz 8 Start — Named Phrases Check', 'alistair/quiz/alistair_quiz_start-quiz-08.mp3', 'Mastery Quiz Eight — Named Phrases Check. Write sentences using a noun phrase, an adverb phrase, and a prepositional phrase. Name the phrase type for one of your answers.'),
  ('quiz.start_quiz_09', 'alistair', 'quiz', 'Quiz 9 Start — Clause Check', 'alistair/quiz/alistair_quiz_start-quiz-09.mp3', 'Mastery Quiz Nine — Clause Check. Six prompts. Join clauses using the conjunction shown. Because, when, although, while — each one creates a different meaning.'),
  ('quiz.start_quiz_10', 'alistair', 'quiz', 'Quiz 10 Start — Fronted Adverbial Check', 'alistair/quiz/alistair_quiz_start-quiz-10.mp3', 'Mastery Quiz Ten — Fronted Adverbial Check. Move the adverb or phrase to the front. Do not forget the comma. Five prompts.'),
  ('quiz.start_quiz_11', 'alistair', 'quiz', 'Quiz 11 Start — Compound and Complex Check', 'alistair/quiz/alistair_quiz_start-quiz-11.mp3', 'Mastery Quiz Eleven — Compound and Complex Check. You will write compound sentences and complex sentences. The prompts will tell you which conjunction to use.'),
  ('quiz.start_quiz_12', 'alistair', 'quiz', 'Quiz 12 Start — Phrases and Transitions Check', 'alistair/quiz/alistair_quiz_start-quiz-12.mp3', 'Mastery Quiz Twelve — Phrases and Transitions Check. Use a stacked adjective pair, a relative clause, and at least one transitional phrase in your sentences.'),
  ('quiz.start_quiz_13', 'alistair', 'quiz', 'Quiz 13 Start — Programme Mastery', 'alistair/quiz/alistair_quiz_start-quiz-13.mp3', 'Mastery Quiz Thirteen — Programme Mastery. This is the final checkpoint. Write the most controlled, complex sentences you can. Use everything you know. This is your best work.'),
  ('step.applied_prepwp', 'alistair', 'step_instruction', 'Applied pre-PWP note', 'alistair/step-instructions/alistair_step_applied-prepwp.mp3', 'You learned this before PWP started. Apply it now — it is already part of your toolkit.'),
  ('step.command_no_subject', 'alistair', 'step_instruction', 'Command — no subject note', 'alistair/step-instructions/alistair_step_command-no-subject.mp3', 'Commands have no subject. Begin with the verb. No you needed — the reader understands.'),
  ('step.consolidation_intro', 'alistair', 'step_instruction', 'Consolidation step intro', 'alistair/step-instructions/alistair_step_consolidation-intro.mp3', 'This is a consolidation step. You have seen this formula before — this time, try it confidently.'),
  ('step.example_prompt', 'alistair', 'step_instruction', 'Example prompt', 'alistair/step-instructions/alistair_step_example-prompt.mp3', 'Here is an example to guide you.'),
  ('step.formula_intro', 'alistair', 'step_instruction', 'Formula intro', 'alistair/step-instructions/alistair_step_formula-intro.mp3', 'Here is your formula for this step.'),
  ('step.fronted_comma', 'alistair', 'step_instruction', 'Fronted comma rule', 'alistair/step-instructions/alistair_step_fronted-comma.mp3', 'When you move a word or phrase to the front of a sentence, always follow it with a comma.'),
  ('step.gap_slot_intro', 'alistair', 'step_instruction', 'Gap slot intro', 'alistair/step-instructions/alistair_step_gap-slot-intro.mp3', 'You know all of these words. The coloured slot is the new element — type it in yourself.'),
  ('step.new_element_intro', 'alistair', 'step_instruction', 'New element intro', 'alistair/step-instructions/alistair_step_new-element-intro.mp3', 'This step introduces something new. Look at the formula carefully, then look at the example before you write.'),
  ('step.paragraph_close', 'alistair', 'step_instruction', 'Paragraph close prompt', 'alistair/step-instructions/alistair_step_paragraph-close.mp3', 'Write your closing sentence. Make it more complex than your support sentences. Finish with power.'),
  ('step.paragraph_lead', 'alistair', 'step_instruction', 'Paragraph lead prompt', 'alistair/step-instructions/alistair_step_paragraph-lead.mp3', 'Your formula sentence for this step will become the Lead sentence of your paragraph.'),
  ('step.paragraph_support', 'alistair', 'step_instruction', 'Paragraph support prompt', 'alistair/step-instructions/alistair_step_paragraph-support.mp3', 'Now add two or three support sentences. Write freely — use your own ideas to develop the lead.'),
  ('step.question_flip', 'alistair', 'step_instruction', 'Question auxiliary flip', 'alistair/step-instructions/alistair_step_question-flip.mp3', 'To form a question, move the auxiliary verb to the front. The rest of the sentence stays the same.'),
  ('step.subject_chip', 'alistair', 'step_instruction', 'Subject chip prompt', 'alistair/step-instructions/alistair_step_subject-chip.mp3', 'Use this subject in your sentence.'),
  ('step.tense_variety', 'alistair', 'step_instruction', 'Tense variety note', 'alistair/step-instructions/alistair_step_tense-variety.mp3', 'All three tenses — past, present, and continuous — with the same subject. Only the tense changes.'),
  ('step.three_stage', 'alistair', 'step_instruction', 'Three-stage evolution note', 'alistair/step-instructions/alistair_step_three-stage.mp3', 'Three forms, one person. Sam. The boy. He. Watch how the subject changes as the formula grows.'),
  ('step.transition_arrow', 'alistair', 'step_instruction', 'Transition arrow note', 'alistair/step-instructions/alistair_step_transition-arrow.mp3', 'Notice the arrow. The same person is written two ways. The formula has changed — the meaning has not.'),
  ('step.word_bank_intro', 'alistair', 'step_instruction', 'Word bank intro', 'alistair/step-instructions/alistair_step_word-bank-intro.mp3', 'The words you need are in the bank below. Tap them in the right order to build your sentence.'),
  ('step.write_now', 'alistair', 'step_instruction', 'Write now prompt', 'alistair/step-instructions/alistair_step_write-now.mp3', 'Now write your sentence.'),
  ('level_start.level_01', 'alistair', 'level_start', 'Level 1 Welcome', 'alistair/level-start/alistair_level-start_level-01.mp3', 'Welcome to Level One. This is where PWP begins! Today you will write a simple sentence: a noun and a verb in the past tense. Think: Sam ran. That is your starting point. Let''s go.'),
  ('level_start.level_02', 'alistair', 'level_start', 'Level 2 Welcome', 'alistair/level-start/alistair_level-start_level-02.mp3', 'Well done for reaching Level Two. You already know the past tense. Today we add two more: the present tense and the continuous tense. One subject, three ways of writing about time. Ready?'),
  ('level_start.level_03', 'alistair', 'level_start', 'Level 3 Welcome', 'alistair/level-start/alistair_level-start_level-03.mp3', 'Level Three. You have mastered all three tenses. Today''s new element is the continuous tense on its own — the helping verb plus the main verb with -ing. Sam is running. Watch for the pattern.'),
  ('level_start.level_04', 'alistair', 'level_start', 'Level 4 Welcome', 'alistair/level-start/alistair_level-start_level-04.mp3', 'Level Four — the object noun. So far your subject has been doing things. Now we add what they did it to. Sam kicked a ball. The ball is the object. One new piece joins the chain today.'),
  ('level_start.level_05', 'alistair', 'level_start', 'Level 5 Welcome', 'alistair/level-start/alistair_level-start_level-05.mp3', 'Level Five. You know Sam kicked a ball. Today we add a determiner in front of the subject noun. Sam becomes The boy. These two words mean the same person — just written differently. Watch the arrow.'),
  ('level_start.level_06', 'alistair', 'level_start', 'Level 6 Welcome', 'alistair/level-start/alistair_level-start_level-06.mp3', 'Level Six — the determiner moves to the object as well. The boy kicked the ball. Both nouns now have a determiner. Today you will practise putting the right determiner in front of each noun.'),
  ('level_start.level_07', 'alistair', 'level_start', 'Level 7 Welcome', 'alistair/level-start/alistair_level-start_level-07.mp3', 'Level Seven introduces the adjective. An adjective describes a noun. Today it sits in front of the subject noun: The tall boy. One new word — but it changes how your sentence feels completely.'),
  ('level_start.level_08', 'alistair', 'level_start', 'Level 8 Welcome', 'alistair/level-start/alistair_level-start_level-08.mp3', 'Level Eight. The adjective moves to the object noun this time. Sam kicked the red ball. You know where adjectives go — now place one in front of the object and see what changes.'),
  ('level_start.level_09', 'alistair', 'level_start', 'Level 9 Welcome', 'alistair/level-start/alistair_level-start_level-09.mp3', 'Level Nine — adjectives on both nouns at once. The tall boy kicked the red ball. This is the fullest sentence you have written so far. Two adjectives, two nouns, one verb. Build it step by step.'),
  ('level_start.level_10', 'alistair', 'level_start', 'Level 10 Welcome', 'alistair/level-start/alistair_level-start_level-10.mp3', 'Level Ten introduces the adverb of manner. Adverbs tell us how something happened. Sam ran quickly. The adverb sits at the end of the sentence for now. One word — and it brings the action to life.'),
  ('level_start.level_11', 'alistair', 'level_start', 'Level 11 Welcome', 'alistair/level-start/alistair_level-start_level-11.mp3', 'Level Eleven — the adverb of time. Instead of how, this adverb tells us when. Sam ran yesterday. It sits at the end of the sentence, just like the adverb of manner. Try to feel the difference.'),
  ('level_start.level_12', 'alistair', 'level_start', 'Level 12 Welcome', 'alistair/level-start/alistair_level-start_level-12.mp3', 'Level Twelve adds the adverb of place. Sam ran outside. Where did he run? Outside. Three types of adverb now: manner, time, and place. Today you focus on place.'),
  ('level_start.level_13', 'alistair', 'level_start', 'Level 13 Welcome', 'alistair/level-start/alistair_level-start_level-13.mp3', 'Level Thirteen is a combination level. You will use manner, time, and place adverbs in the same sentence. The tall boy kicked the red ball hard, yesterday, outside. Build the longest sentence you have written yet.'),
  ('level_start.level_14', 'alistair', 'level_start', 'Level 14 Welcome', 'alistair/level-start/alistair_level-start_level-14.mp3', 'Level Fourteen — the pronoun. A pronoun replaces a noun. Sam becomes He. The boy becomes He. Watch carefully: in step three you will see all three forms — Sam, The boy, He — for the very same person.'),
  ('level_start.level_15', 'alistair', 'level_start', 'Level 15 Welcome', 'alistair/level-start/alistair_level-start_level-15.mp3', 'Level Fifteen. The pronoun goes into full combinations — with adjectives, adverbs, and the continuous tense. He kicked the red ball hard. She kicks the ball every day. Same structure, different subject form.'),
  ('level_start.level_16', 'alistair', 'level_start', 'Level 16 Welcome', 'alistair/level-start/alistair_level-start_level-16.mp3', 'Level Sixteen introduces the preposition. A preposition tells us about position or direction. Sam ran into school. The preposition sits before a noun and shows where the action went. One new word — a powerful one.'),
  ('level_start.level_17', 'alistair', 'level_start', 'Level 17 Welcome', 'alistair/level-start/alistair_level-start_level-17.mp3', 'Level Seventeen. The preposition phrase grows. We add a determiner after the preposition: into the garden. Sam ran into the garden. The phrase is more precise now — the reader can picture exactly where.'),
  ('level_start.level_18', 'alistair', 'level_start', 'Level 18 Welcome', 'alistair/level-start/alistair_level-start_level-18.mp3', 'Level Eighteen — the full preposition phrase. Preposition, determiner, and now an adjective too: into the dark garden. Every word earns its place. This phrase will stay in your writing toolkit forever.'),
  ('level_start.level_19', 'alistair', 'level_start', 'Level 19 Welcome', 'alistair/level-start/alistair_level-start_level-19.mp3', 'Level Nineteen. The preposition phrase stretches further — adjective added to the object inside it. The tall boy ran into the dark, cold garden. You are writing long, controlled sentences now. Trust the formula.'),
  ('level_start.level_20', 'alistair', 'level_start', 'Level 20 Welcome', 'alistair/level-start/alistair_level-start_level-20.mp3', 'Level Twenty — questions. Today the sentence changes its purpose. Instead of telling, it asks. Did Sam run? The auxiliary verb moves to the front. The formula flips — but you know all the words already.'),
  ('level_start.level_21', 'alistair', 'level_start', 'Level 21 Welcome', 'alistair/level-start/alistair_level-start_level-21.mp3', 'Level Twenty-One. Wh- questions. Where, why, what, when, who. The question word comes first, then the auxiliary, then the subject. Where did Sam run? One new word at the front changes everything.'),
  ('level_start.level_22', 'alistair', 'level_start', 'Level 22 Welcome', 'alistair/level-start/alistair_level-start_level-22.mp3', 'Level Twenty-Two — commands. A command has no subject. The verb starts the sentence. Kick the ball! Run into the garden! Short, direct, powerful. This is a completely new sentence type.'),
  ('level_start.level_23', 'alistair', 'level_start', 'Level 23 Welcome', 'alistair/level-start/alistair_level-start_level-23.mp3', 'Level Twenty-Three — exclamations. What a tall boy! How quickly the boy ran! These sentences express strong feeling. They start with What or How and end with an exclamation mark. Feel the emotion in the words.'),
  ('level_start.level_24', 'alistair', 'level_start', 'Level 24 Welcome', 'alistair/level-start/alistair_level-start_level-24.mp3', 'Level Twenty-Four. You have been using noun phrases for a long time. Today you name them. A noun phrase is a determiner, an adjective, and a noun working together. The very tall boy is a noun phrase. Naming it helps you control it.'),
  ('level_start.level_25', 'alistair', 'level_start', 'Level 25 Welcome', 'alistair/level-start/alistair_level-start_level-25.mp3', 'Level Twenty-Five — adverb phrases and prepositional phrases. Very quickly is an adverb phrase. Into the dark garden is a prepositional phrase. These groups of words act as single units. You have been writing them already — now you know what to call them.'),
  ('level_start.level_26', 'alistair', 'level_start', 'Level 26 Welcome', 'alistair/level-start/alistair_level-start_level-26.mp3', 'Level Twenty-Six. A clause is a group of words with a subject and a verb. An independent clause makes complete sense on its own. The boy kicked the ball — that is an independent clause. Today you name it and use it.'),
  ('level_start.level_27', 'alistair', 'level_start', 'Level 27 Welcome', 'alistair/level-start/alistair_level-start_level-27.mp3', 'Level Twenty-Seven — subordinating conjunctions: because, when, and although. These words join a main clause to a dependent clause. Sam ran because he was late. The dependent clause needs the main clause to make sense.'),
  ('level_start.level_28', 'alistair', 'level_start', 'Level 28 Welcome', 'alistair/level-start/alistair_level-start_level-28.mp3', 'Level Twenty-Eight extends your conjunction toolkit: if, unless, before, after, while, and until. Each one shows a different relationship between two clauses. The boy ran until he was exhausted. One conjunction, one relationship, one meaning.'),
  ('level_start.level_29', 'alistair', 'level_start', 'Level 29 Welcome', 'alistair/level-start/alistair_level-start_level-29.mp3', 'Level Twenty-Nine — fronted adverbials. Take your adverb and move it to the front of the sentence, followed by a comma. Quickly, the boy ran. The comma is essential. Moving the adverb changes the rhythm and the emphasis.'),
  ('level_start.level_30', 'alistair', 'level_start', 'Level 30 Welcome', 'alistair/level-start/alistair_level-start_level-30.mp3', 'Level Thirty. The prepositional phrase moves to the front this time. Into the garden, the tall boy ran. Preposition phrase, comma, then the main clause. You are controlling the shape of the sentence now — not just the words.'),
  ('level_start.level_31', 'alistair', 'level_start', 'Level 31 Welcome', 'alistair/level-start/alistair_level-start_level-31.mp3', 'Level Thirty-One is a milestone. The paragraph phase begins. From now on, your formula sentence becomes the Lead — the opening sentence of a full paragraph. You will add support sentences and a powerful close. This is real writing.'),
  ('level_start.level_32', 'alistair', 'level_start', 'Level 32 Welcome', 'alistair/level-start/alistair_level-start_level-32.mp3', 'Level Thirty-Two — compound sentences. Two main clauses joined by a coordinating conjunction: and, but, or, so, yet, for. The boy ran and the dog chased him. Each clause could stand alone — the conjunction links them as equals.'),
  ('level_start.level_33', 'alistair', 'level_start', 'Level 33 Welcome', 'alistair/level-start/alistair_level-start_level-33.mp3', 'Level Thirty-Three — complex sentences with the subordinate clause first. Because he was angry, the tall boy kicked the ball. The dependent clause comes before the main clause now — and a comma separates them.'),
  ('level_start.level_34', 'alistair', 'level_start', 'Level 34 Welcome', 'alistair/level-start/alistair_level-start_level-34.mp3', 'Level Thirty-Four — stacked adjectives and embedded relative clauses. The tall, strong boy who trained every day. Two adjectives stacked together. A who-clause embedded inside the noun phrase. Your sentences are becoming precise and textured.'),
  ('level_start.level_35', 'alistair', 'level_start', 'Level 35 Welcome', 'alistair/level-start/alistair_level-start_level-35.mp3', 'Level Thirty-Five — transitional phrases. First, next, finally, however, as a result. These phrases sit at the start of a sentence and guide the reader from one idea to the next. You are writing to be read now. This is the final level.')
